describe('API Response Caching', () => {
  beforeEach(() => {
    cy.visit('/dashboard');
  });

  it('should cache API responses for instant repeat visits', () => {
    // First visit - API call should be made
    cy.intercept('GET', '/api/data').as('firstRequest');
    cy.get('[data-testid="load-data-button"]').click();
    cy.wait('@firstRequest');
    cy.get('[data-testid="data-content"]').should('be.visible');
    cy.get('[data-testid="data-content"]').should('contain', 'Data loaded successfully');

    // Second visit - API call should be skipped due to cache
    cy.reload();
    cy.get('[data-testid="load-data-button"]').click();
    cy.get('[data-testid="data-content"]').should('be.visible');
    cy.get('[data-testid="data-content"]').should('contain', 'Data loaded successfully');

    // Verify no network request was made on second visit
    cy.get('@firstRequest').then((interception) => {
      expect(interception.response.statusCode).to.equal(200);
    });
    cy.get('[data-testid="cache-status"]').should('contain', 'Cached');
  });

  it('should invalidate cache when data is updated', () => {
    // First visit - API call and cache
    cy.intercept('GET', '/api/data').as('firstRequest');
    cy.get('[data-testid="load-data-button"]').click();
    cy.wait('@firstRequest');
    cy.get('[data-testid="data-content"]').should('contain', 'Data loaded successfully');

    // Update data via API
    cy.intercept('PUT', '/api/data').as('updateData');
    cy.get('[data-testid="edit-data-button"]').click();
    cy.get('[data-testid="data-input"]').clear().type('Updated data');
    cy.get('[data-testid="save-button"]').click();
    cy.wait('@updateData');

    // Verify cache is invalidated and new data is fetched
    cy.reload();
    cy.get('[data-testid="load-data-button"]').click();
    cy.intercept('GET', '/api/data').as('refetchRequest');
    cy.wait('@refetchRequest');
    cy.get('[data-testid="data-content"]').should('contain', 'Updated data');
    cy.get('[data-testid="cache-status"]').should('contain', 'Refreshed');
  });
});
